for (std::size_t i = 0; i < P1.size(); ++i) {
    const auto& p1_start = P1[i];
    const auto& p1_end = P1[(i + 1) % P1.size()];

    for (std::size_t j = 0; j < P2.size(); ++j) {
        const auto& p2_start = P2[j];
        const auto& p2_end = P2[(j + 1) % P2.size()];

        // Check if the current edges intersect
        auto ccw = [](const Point2d& a, const Point2d& b, const Point2d& c) {
            return (c.y - a.y) * (b.x - a.x) > (b.y - a.y) * (c.x - a.x);
        };

        bool intersect = ccw(p1_start, p2_start, p2_end) != ccw(p1_end, p2_start, p2_end) &&
                         ccw(p1_start, p1_end, p2_start) != ccw(p1_start, p1_end, p2_end);

        if (intersect) {
            return true;
        }
    }
}

// Check if any vertex of P1 is inside P2
auto point_in_polygon = [](const Point2d& point, const Polygon2d& polygon) {
    bool inside = false;
    for (std::size_t i = 0, j = polygon.size() - 1; i < polygon.size(); j = i++) {
        const auto& pi = polygon[i];
        const auto& pj = polygon[j];

        if (((pi.y > point.y) != (pj.y > point.y)) &&
            (point.x < (pj.x - pi.x) * (point.y - pi.y) / (pj.y - pi.y) + pi.x)) {
            inside = !inside;
        }
    }
    return inside;
};

for (const auto& point : P1) {
    if (point_in_polygon(point, P2)) {
        return true;
    }
}

// Check if any vertex of P2 is inside P1
for (const auto& point : P2) {
    if (point_in_polygon(point, P1)) {
        return true;
    }
}

return false;
